   if !self.terrain_ok(kind,cell){self.feedback(if kind==9{48}else if matches!(kind,4|5|6){39}else{34},0.);return 0.;}let footprint=footprint(kind,cell);if footprint.is_empty()||footprint.iter().any(|c|!land(self.terrain[*c])||self.walls[*c]>0.||self.occupancy[*c]>=0)||self.units.iter().any(|u|u.kind>0&&footprint.contains(&u.cell)){self.feedback(2,0.);return 0.;}
