  if (3_000_001..=3_004_737).contains(&code){let n=(code-3_000_000)as usize;let center=n/100;let bay=(n%100)/10;let model=n%10;if center>=BUILDINGS||bay>=4||model<1||model>7||!self.live_building(center)||self.buildings[center].kind!=2{self.feedback(52,0.);return 0.;}if self.tech<GTECH[model]{self.feedback(32,0.);return 0.;}if self.gpus.iter().any(|g|g.model>0&&g.center==center&&g.bay==bay){self.feedback(2,0.);return 0.;}let Some(i)=self.gpus.iter().position(|g|g.model==0)else{self.feedback(49,0.);return 0.;};if !self.can_spend(GCOST[model],false){return 0.;}self.credits-=GCOST[model];self.gpus[i]=Gpu{model,center,bay,tier:1,invested:GCOST[model],powered:false};self.changed(false);self.networks();self.feedback(20,GCOST[model]);return 1.;}
