static GAME:Mutex<Option<Game>>=Mutex::new(None);
fn game<T>(f:impl FnOnce(&mut Game)->T)->T{let mut g=GAME.lock().unwrap_or_else(|p|p.into_inner());f(g.get_or_insert_with(||Game::new(1,load_unlock(),0)))}
